Add({
	kind = "figure",
	id = "morganth",
	title = "Morganth",
	subtitle = "Warlock of the Tower of Ilgalar",
	tier = "B",
	region = "redridge-mountains",
	npc = { 397 },
	allegiance = "Himself · the Shadowhide gnolls",
	found = "The top of the Tower of Ilgalar",
	pin = { x = 80.1, y = 49.5 },
	unlock = {
		{ type = "target" },
	},
	hint = "Climb the Tower of Ilgalar and face its master.",
	sections = {
		{
			title = "Summary",
			text = [=[Morganth is a human warlock who dwells in the {link:tower-of-ilgalar}Tower of Ilgalar{/link}. Long ago he studied in the mage tower of {link:stormwind-city}Stormwind{/link}, one of three who learned there together. He fell to the dark arts, and when he would not turn back he was banished. He took with him a sealed book of shadow magic. Now he commands the {link:shadowhide-gnolls}Shadowhide gnolls{/link}, speaks to them through enchanted pendants and summons demons to his side.]=],
		},
		{
			title = "Significance",
			text = [=[Morganth is the hidden author of {link:redridge-mountains}Redridge{/link}'s ruin. It was his magic that fed the {link:blackrock-mountain}Blackrock{/link} savagery at {link:stonewatch-keep}Stonewatch Keep{/link}. He is also the rival of the High Mage {link:theocritus}Theocritus{/link}, who has watched him from {link:elwynn-forest}Elwynn{/link} for a long time.]=],
		},
		{
			title = "Deeds",
			text = [=[• He made an alliance with {link:gath-ilzogg}Gath'Ilzogg{/link} and the {link:blackrock-clan}Blackrock clan{/link}, and helped them take {link:stonewatch-keep}Stonewatch Keep{/link}.
• He turned on the orcs soon after, raised his own tower and bound the {link:shadowhide-gnolls}Shadowhide gnolls{/link} to his service.
• He keeps Ur's Treatise on Shadow Magic, although he never broke the seals the mages of {link:stormwind-city}Stormwind{/link} set on it.
• He seeks the {red:scythe-of-elune}Scythe of Elune{/red}.]=],
		},
	},
	chapters = {
		{
			key = "the-broken-alliance",
			title = "The Broken Alliance",
			hint = "Help Theocritus look into the keep of the orcs.",
			unlock = {
				{ type = "quest", id = 248 },
			},
			text = [=[The Eye of {link:tower-of-azora}Azora{/link} showed {link:theocritus}Theocritus{/link} a warlock at war with the orcs he had once helped. Why the two had fallen out, not even {link:magistrate-solomon}Magistrate Solomon{/link} could say. To learn more, the High Mage hid a glyph at the top of the watchtower beside {link:stonewatch-keep}Stonewatch Keep{/link}, and he began to read the minds of the orcs inside.]=],
		},
		{
			key = "the-scythe",
			title = "The Scythe",
			hint = "Do what Theocritus is not prepared to do himself.",
			unlock = {
				{ type = "quest", id = 249 },
			},
			text = [=[At last {link:theocritus}Theocritus{/link} learned what Morganth sought: the Scythe of Elune. He feared that the warlock had already found it, and that {link:stormwind-city}Stormwind{/link} would soon feel his power. The High Mage would not face Morganth himself, so another climbed the {link:tower-of-ilgalar}Tower of Ilgalar{/link} in his stead. Morganth's Pendant of Shadow came back to {link:elwynn-forest}Elwynn{/link}, and Theocritus called the kingdom saved from a grave peril.]=],
		},
	},
	mentions = {
		{
			text = "{link:magistrate-solomon}Solomon{/link}'s Law",
			unlock = {
				{ type = "quest", id = 91 },
			},
		},
		{
			text = "{link:theocritus}Theocritus{/link}' Retrieval",
			unlock = {
