Add({
	kind = "topic",
	id = "blackrock-clan",
	title = "Blackrock Clan",
	aliases = { "Blackrock clan", "Blackrock orcs" },
	unlock = {
		{ type = "read" },
	},
	category = "group",
	sections = {
		{
			title = "Summary",
			text = [=[The {link:blackrock-mountain}Blackrock{/link} are one of the oldest and most warlike clans of the {link:orcs}orcs{/link}. They were the backbone of the old {link:horde}Horde{/link} and gave it two of its Warchiefs. Long after the Horde's defeat, the Blackrock have kept the old ways of war, and they have never made peace with the humans.]=],
		},
		{
			title = "History",
			text = [=[In the {link:first-war}First War{/link}, the Blackrock chieftain Blackhand led the {link:horde}Horde{/link} as its Warchief, though others pulled the strings behind him. He was slain by one of his own, {link:orgrim-doomhammer}Orgrim Doomhammer{/link}, a Blackrock warrior who then led the Horde to the conquest of {link:stormwind-city}Stormwind{/link}. In the {link:second-war}Second War{/link}, Doomhammer's Horde was broken at {link:blackrock-mountain}Blackrock Mountain{/link} after he had slain {link:anduin-lothar}Anduin Lothar{/link}. Most of the orcs were herded into camps. The Blackrock who escaped took refuge in the mountain that bears their name, and they have held its heights ever since.]=],
		},
		{
			title = "In Redridge",
			text = [=[Now the {link:blackrock-mountain}Blackrock{/link} have come south out of the {link:burning-steppes}Burning Steppes{/link}. Under the warlord {link:gath-ilzogg}Gath'Ilzogg{/link}, and with the dark magic of {link:morganth}Morganth{/link}, they took {link:stonewatch-keep}Stonewatch Keep{/link} and brought down the {link:lake-everstill}Everstill{/link} Bridge. Their outrunners ambush the roads, their shadowcasters carry orbs tainted by demons, and their champions camp by the northern pass. Another war band has entered the far south-east by {link:render-s-valley}Render's Valley{/link}. Yet they have pushed so far into the kingdom that they must forage in the hills for food and arms, and {link:lakeshire}Lakeshire{/link} hopes to starve them out.]=],
		},
		{
			title = "The New Horde",
			text = [=[Not every {link:blackrock-mountain}Blackrock{/link} stayed with the clan. {link:eitrigg}Eitrigg{/link}, who once served the Blackrock war chief, came to hate the demon worshippers who led his people astray. He now serves {link:thrall}Thrall{/link} in {link:orgrimmar}Orgrimmar{/link}, far from the mountain of his old clan.]=],
		},
	},
})

Add({
	kind = "topic",
	id = "shadowhide-gnolls",
	title = "Shadowhide Gnolls",
