	sections = {
		{
			title = "Summary",
			text = [=[The Shadowhide are a clan of {link:gnolls}gnolls{/link} who dwell in {link:galardell-valley}Galardell Valley{/link}, in the north-east of {link:redridge-mountains}Redridge{/link}. They serve the warlock {link:morganth}Morganth{/link}. Their leader is {link:lieutenant-fangore}Lieutenant Fangore{/link}. Their darkweavers practice a shadowy magic, their assassins strike unseen, and their slayers attack {link:orcs}orc{/link} and human alike.]=],
		},
		{
			title = "Bound by Pendants",
			text = [=[Each Shadowhide wears a pendant through which {link:morganth}Morganth{/link} speaks to them. The High Mage {link:theocritus}Theocritus{/link} has spent months trying to reach into those pendants. He has managed to send a message through some of them, and he hopes one day to send an attack through them that would freeze every {link:gnolls}gnoll{/link} that wears one.]=],
		},
		{
			title = "Under the Law",
			text = [=[The court of {link:lakeshire}Lakeshire{/link} declared the Shadowhide guilty of aiding a criminal of the kingdom, a crime punished by death. {link:bailiff-conacher}Bailiff Conacher{/link} pays for their pendants as proof, and the magistrate has put a bounty on {link:lieutenant-fangore}Fangore{/link} himself.]=],
		},
		{
			title = "Foes of All",
			text = [=[The Shadowhide are no friends of the {link:blackrock-mountain}Blackrock{/link}. When {link:morganth}Morganth{/link} turned on his orcish allies, his gnolls turned with him, and orcs have died at their hands as surely as men.]=],
		},
	},
})

